25	/**
26	 * Authoritative check for the owner fields that must be present and non-blank.
27	 * <p>
28	 * Returns the names of any of {@code firstName}, {@code lastName}, {@code address},
29	 * {@code city} or {@code telephone} that are missing (null) or blank, in a stable
30	 * canonical order.
31	 */
32	@Component
33	public class OwnerFieldsValidator {
34	
35	    /**
36	     * @param owner the submitted owner fields (may be {@code null})
37	     * @return the names of the required fields that are missing or blank, in canonical order;
38	     *         empty when every required field is present and non-blank
39	     */
40	    public List<String> findMissingOrBlankFields(OwnerFieldsDto owner) {
41	        List<String> missing = new ArrayList<>();
42	        addIfBlank(missing, "firstName", owner == null ? null : owner.getFirstName());
43	        addIfBlank(missing, "lastName", owner == null ? null : owner.getLastName());
44	        addIfBlank(missing, "address", owner == null ? null : owner.getAddress());
45	        addIfBlank(missing, "city", owner == null ? null : owner.getCity());
46	        addIfBlank(missing, "telephone", owner == null ? null : owner.getTelephone());
47	        return missing;
48	    }
49	
50	    private void addIfBlank(List<String> missing, String fieldName, String value) {
51	        if (value == null || value.isBlank()) {
52	            missing.add(fieldName);
53	        }
54	    }
55	}
